import {ModelRuntime} from '@earendil-works/pi-coding-agent';
import fs from 'node:fs';import path from 'node:path';
const dir=process.env.SDK_CONFIG_DIR,file=path.join(dir,'models.json');fs.mkdirSync(dir,{recursive:true});
const credentials={read:async()=>undefined,list:async()=>[]};
const pick=r=>r.getModels('case').map(m=>({id:m.id,name:m.name,api:m.api,provider:m.provider,baseUrl:m.baseUrl,reasoning:m.reasoning,input:m.input,cost:m.cost,contextWindow:m.contextWindow,maxTokens:m.maxTokens,compat:m.compat,samplingParams:m.samplingParams}));
const error=r=>(r.getError()??null)?.split(file).join('<file>');
try {
fs.writeFileSync(file,'\ufeff{// source comment\n"providers":{"case":{"name":"Case","api":"openai-completions","baseUrl":"https://fixture.invalid/v1","apiKey":"fixture-key","compat":{"supportsStore":false},"models":[{"id":"a","name":"Alpha","contextWindow":4096,"maxTokens":512,"samplingParams":{"temperature":0.25}},],}},}');
const r=await ModelRuntime.create({modelsPath:file,refreshOnCreate:false,credentials});const loaded={models:pick(r),error:error(r)};
await r.refresh({allowNetwork:false});const status=r.getProviderAuthStatus('case');
const replacement={api:'openai-completions',baseUrl:'https://replacement.invalid/v1',apiKey:'fixture-key',models:[{id:'b',reasoning:true,input:['text','image']}],modelOverrides:{b:{name:'Override',cost:{input:2},samplingParams:{top_p:0.7}}}};
fs.writeFileSync(file,JSON.stringify({providers:{case:replacement}}));await r.refresh({allowNetwork:false});const replaced={models:pick(r),error:error(r)};
fs.writeFileSync(file,JSON.stringify({providers:{case:{models:[{id:'no-api'}]}}}));await r.refresh({allowNetwork:false});const structural={models:pick(r),error:error(r)};
fs.writeFileSync(file,JSON.stringify({providers:{case:{baseUrl:'',models:[{id:''}]}}}));await r.refresh({allowNetwork:false});const schema={models:pick(r),error:error(r)};
console.log(JSON.stringify({loaded,status,replaced,structural,schema}));
}finally{fs.unlinkSync(file)}
